class FET:
    about_fet='''   FET stands for file encryption tool. It is a series of tools
used for file encryption. It exists, currently, in 2 different algorithms: AES, AND RSA'''


class FETAPI(FET):
    def kill_program(error_msg=None, title='ERROR'):
        if error_msg!=None:
            mbox.showerror(title, error_msg)            
        sys.exit(1)


    def writefile(file: str, to_write: bytes, write_error_widget, kill_if_failed: bool=False):
        busy = f'{file}: IS BUSY!'
        invalid_perms = f'{file}: INVALID PERMISSIONS!'
        try:
            with open(file, 'wb') as buffer:
                buffer.write(to_write)
                return 0
        except PermissionError:
            if kill_if_failed:
                FETAPI.kill_program(invalid_perms)
            else:
                write_error_widget.config(text=invalid_perms, foreground='red')
                write_error_widget.master.update_idletasks()
                time.sleep(1)
                write_error_widget.destroy()
        except OSError:
            if kill_if_failed:
                FETAPI.kill_program(busy)
            else:
                write_error_widget.config(text=busy, foreground='red')
                write_error_widget.master.update_idletasks()
                time.sleep(1)
                write_error_widget.destroy()
        return 1


    def readfile(file: str, write_error_widget, kill_if_failed: bool=False):
        busy = f'{file}: IS BUSY!'
        not_found = f'{file}: NOT FOUND!'
        invald_perms = f'{file}: INVALID PERMISSIONS!'
        try:
            with open(file, 'rb') as buffer:
                contents = buffer.read()
            return contents
        except PermissionError:
            if kill_if_failed:
                FETAPI.kill_program(invalid_perms)
            else:
                write_error_widget.config(text=invalid_perms, foreground='red')
                write_error_widget.master.update_idletasks()
                time.sleep(1)
                write_error_widget.destroy()
        except FileNotFoundError:
            if kill_if_failed:
                FETAPI.kill_program(not_found)
            else:
                write_error_widget.config(text=not_found, foreground='red')
                write_error_widget.master.update_idletasks()
                time.sleep(1)
                write_error_widget.destroy()
        except OSError:
            if kill_if_failed:
                FETAPI.kill_program(busy)
            else:
                # mbox.showerror(error_box_title, busy)
                write_error_widget.config(text=not_found, foreground='red')
                write_error_widget.master.update_idletasks()
                time.sleep(1)
                write_error_widget.destroy()


