    def encrypt_files(master_widget, files, plaintext_key, keylength, recurse=True, hmac_hash_module=Hash.SHA512):
        salt = os.urandom(32)
        processed_files = {'succeeded': [], 'failed': []}
        for file in files:
            if os.path.isfile(file):
                if FETAESGUIAPI.encrypt_file(master_widget, file, plaintext_key, salt, keylength, kill_if_failed=False, hash_module=hmac_hash_module)==0:
                    processed_files['succeeded'].append(file)
                else:
                    processed_files['failed'].append(file)
            elif recurse and os.path.isdir(file):
                dir_recursion_results = FETAESGUIAPI.encrypt_files( master_widget, [ os.path.join(file, entry.name) for entry in os.scandir(file) ], plaintext_key, hmac_hash_module=hmac_hash_module)
                processed_files['succeeded'].extend(dir_recursion_results.get('succeeded'))
                processed_files['failed'].extend(dir_recursion_results.get('failed'))
            else:
                processed_files['failed'].append(file)
        return processed_files


    def decrypt_files(master_widget, files, plaintext_key, keylength, recurse=True, hmac_hash_module=Hash.SHA512):
        processed_files = {'succeeded': [], 'failed': []}
        for file in files:
            if os.path.isfile(file):
                if FETAESGUIAPI.decrypt_file(master_widget, file, plaintext_key, keylength, kill_if_failed=False, hash_module=hmac_hash_module)==0:
                    processed_files['succeeded'].append(file)
                else:
                    processed_files['failed'].append(file)
            elif recurse and os.path.isdir(file):
                dir_recursion_results = FETAESGUIAPI.decrypt_files( master_widget, [ os.path.join(file, entry) for entry in os.listdir(file) ], plaintext_key, hmac_hash_module=hmac_hash_module )
                if dir_recursion_results==None:
                    continue
                processed_files['succeeded'].extend(dir_recursion_results.get('succeeded'))
                processed_files['failed'].extend(dir_recursion_results.get('failed'))
            else:
                processed_files.append(file)
        return processed_files


